window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d6091bd5b16093e5"]={"versions": [{"id": "FIG-d6091bd5b16093e5", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/UML-basiert). Das Diagramm beschreibt die methodische Aktivität zur Konfiguration von Compiler-Speicherklassen im Kontext des Memory Mapping (MemMap) für AUTOSAR-Softwarekomponenten und Basissoftware-Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rollen:\n<ul class=\"fig-list\"><li><code>Basic Software Module Developer</code> (Kardinalität <code>1</code>)\n</li><li><code>Software Component Developer</code> (Kardinalität <code>0..1</code>)\n</li></ul>\n</li><li>Aktivität / Task:\n<ul class=\"fig-list\"><li><code>Configure Compiler Memory Classes</code> (Pfeilsymbol als Aktivitätsknoten)\n</li></ul>\n</li><li>Artefakt / Arbeitsergebnis:\n<ul class=\"fig-list\"><li><code>BSW Module Preconfigured</code> (Dokument- bzw. Dateisymbol)\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Rollenbeziehungen mit Stereotyp <code>«performs»</code> von beiden Entwicklerrollen auf die Aktivität <code>Configure Compiler Memory Classes</code>.\n</li><li>Ausgabekante mit Stereotyp <code>«output»</code>, Rollenbezeichnung <code>+MemMap config for compiler memclasses</code> und Multiplizität <code>1..*</code> von der Aktivität auf das Artefakt <code>BSW Module Preconfigured</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Configure Compiler Memory Classes</code> wird verbindlich durch genau einen <code>Basic Software Module Developer</code> ausgeführt (Multiplizität <code>1</code>). Optional kann zusätzlich ein <code>Software Component Developer</code> beteiligt sein (Multiplizität <code>0..1</code>). Die Durchführung generiert bzw. aktualisiert mindestens ein oder mehrere Konfigurationsartefakte (<code>1..*</code>), konkret die MemMap-Konfiguration für Compiler-Memory-Classes (<code>+MemMap config for compiler memclasses</code>), abgelegt im Artefakt <code>BSW Module Preconfigured</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für BSW-Modulentwickler und SWC-Entwickler bei der Definition systemspezifischer Compiler-Abstraktions- und Speicherzuordnungsstrukturen. Das Artefakt muss mindestens einfach vorliegen (<code>1..*</code>), um die Speichereigenschaften und Compiler-Pragmas/Makros für das nachfolgende Generieren der MemMap-Headerdateien bereitzustellen.</p>"}, {"id": "FIG-f7f4b398b1f0295e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/UML-basiert). Das Diagramm beschreibt die methodische Aktivität zur Konfiguration von Compiler-Speicherklassen im Kontext des Memory Mapping (MemMap) für AUTOSAR-Softwarekomponenten und Basissoftware-Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rollen:\n<ul class=\"fig-list\"><li><code>Basic Software Module Developer</code> (Kardinalität <code>1</code>)\n</li><li><code>Software Component Developer</code> (Kardinalität <code>0..1</code>)\n</li></ul>\n</li><li>Aktivität / Task:\n<ul class=\"fig-list\"><li><code>Configure Compiler Memory Classes</code> (Pfeilsymbol als Aktivitätsknoten)\n</li></ul>\n</li><li>Artefakt / Arbeitsergebnis:\n<ul class=\"fig-list\"><li><code>BSW Module</code> (Dokument- bzw. Dateisymbol; Beschriftung am unteren Bildrand abgeschnitten)\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Rollenbeziehungen mit Stereotyp <code>«performs»</code> von beiden Entwicklerrollen auf die Aktivität <code>Configure Compiler Memory Classes</code>.\n</li><li>Ausgabekante mit Stereotyp <code>«output»</code>, Rollenbezeichnung <code>+MemMap config for compiler memclasses</code> und Multiplizität <code>1..*</code> von der Aktivität auf das Artefakt <code>BSW Module</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Configure Compiler Memory Classes</code> wird verbindlich durch genau einen <code>Basic Software Module Developer</code> ausgeführt (Multiplizität <code>1</code>). Optional kann zusätzlich ein <code>Software Component Developer</code> beteiligt sein (Multiplizität <code>0..1</code>). Die Durchführung generiert bzw. aktualisiert mindestens ein oder mehrere Konfigurationsartefakte (<code>1..*</code>), konkret die MemMap-Konfiguration für Compiler-Memory-Classes (<code>+MemMap config for compiler memclasses</code>), abgelegt im Artefakt <code>BSW Module Preconfigured</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für BSW-Modulentwickler und SWC-Entwickler bei der Definition systemspezifischer Compiler-Abstraktions- und Speicherzuordnungsstrukturen. Das Artefakt muss mindestens einfach vorliegen (<code>1..*</code>), um die Speichereigenschaften und Compiler-Pragmas/Makros für das nachfolgende Generieren der MemMap-Headerdateien bereitzustellen.</p>"}, {"id": "FIG-9885b0d20bdd502f", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätendiagramm (SPEM-/UML-basiert). Das Diagramm beschreibt die methodische Aktivität zur Konfiguration von Compiler-Speicherklassen im Kontext des Memory Mapping (MemMap) für AUTOSAR-Softwarekomponenten und Basissoftware-Module.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Rollen:\n<ul class=\"fig-list\"><li><code>Basic Software Module Developer</code> (Kardinalität <code>1</code>)\n</li><li><code>Software Component Developer</code> (Kardinalität <code>0..1</code>)\n</li></ul>\n</li><li>Aktivität / Task:\n<ul class=\"fig-list\"><li><code>Configure Compiler Memory Classes</code> (Pfeilsymbol als Aktivitätsknoten)\n</li></ul>\n</li><li>Artefakt / Arbeitsergebnis:\n<ul class=\"fig-list\"><li><code>BSW Module</code> (Dokument- bzw. Dateisymbol; Beschriftung am unteren Bildrand abgeschnitten)\n</li></ul>\n</li><li>Beziehungen:\n<ul class=\"fig-list\"><li>Rollenbeziehungen mit Stereotyp <code>«performs»</code> von beiden Entwicklerrollen auf die Aktivität <code>Configure Compiler Memory Classes</code>.\n</li><li>Ausgabekante mit Stereotyp <code>«output»</code>, Rollenbezeichnung <code>+MemMap config for compiler memclasses</code> und Multiplizität <code>1..*</code> von der Aktivität auf das Artefakt <code>BSW Module</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Configure Compiler Memory Classes</code> wird verbindlich durch genau einen <code>Basic Software Module Developer</code> ausgeführt (Multiplizität <code>1</code>). Optional kann zusätzlich ein <code>Software Component Developer</code> beteiligt sein (Multiplizität <code>0..1</code>). Die Durchführung generiert bzw. aktualisiert mindestens ein oder mehrere Konfigurationsartefakte (<code>1..*</code>), konkret die MemMap-Konfiguration für Compiler-Memory-Classes (<code>+MemMap config for compiler memclasses</code>), abgelegt im Artefakt <code>BSW Module Preconfigured</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für BSW-Modulentwickler und SWC-Entwickler bei der Definition systemspezifischer Compiler-Abstraktions- und Speicherzuordnungsstrukturen. Das Artefakt muss mindestens einfach vorliegen (<code>1..*</code>), um die Speichereigenschaften und Compiler-Pragmas/Makros für das nachfolgende Generieren der MemMap-Headerdateien bereitzustellen.</p>"}], "trans": [{"from": "FIG-d6091bd5b16093e5", "to": "FIG-f7f4b398b1f0295e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Beschriftung des Ergebnis-Artefakts unten rechts ist abgeschnitten („BSW Module Preconfigured“ zu „BSW Module“ verkürzt, untere Zeile entfällt im sichtbaren Bildbereich).\n</li><li>Der Textblock „Configure Compiler Memory Classes“ wurde umbrochen („Configure Compiler“ / „Memory Classes“ statt dreizeilig mit „Classes“ allein).\n</li><li>Geringfügige Anpassungen des Bildausschnitts und der Elementplatzierung.\n</li></ul>"}, {"from": "FIG-f7f4b398b1f0295e", "to": "FIG-9885b0d20bdd502f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
